SELECT

FROM extra_works w
WHERE w.extra_work_id = #{extraWorkId}

SELECT , p.project_name, p.client_id, p.company_id, cl.client_name, co.company_name FROM extra_works w JOIN projects p ON w.project_id = p.project_id LEFT JOIN clients cl ON p.client_id = cl.client_id LEFT JOIN companies co ON p.company_id = co.company_id WHERE p.deleted_at IS NULL
AND p.client_id = #{clientId}
AND p.company_id = #{companyId}
AND w.billed_date IS NULL AND NOT EXISTS (SELECT 1 FROM billing_statement_items si WHERE si.extra_work_id = w.extra_work_id)
ORDER BY w.work_date DESC, w.extra_work_id DESC
